// article: the DEC VT220's own glyphs, 10 dots wide by 20 scan lines, with the terminal's
// built-in inter-character spacing and the vertical 2x the VT220 scanned at.
//
// Glyphs: DEC-Fonts by htayj (https://github.com/htayj/DEC-Fonts), MIT licensed, decoded
//   from the VT220 character-ROM dump published by Paul Flo Williams (vt100.net) following
//   the VT220 technical manual. Only printable ASCII 0x20-0x7E is carried here.
//   SPDX-License-Identifier: MIT
//
// Row value: 16 bits, bit 15 = LEFTMOST dot (TerminalFont/glyphRow, host/terminal/font.h);
// the glyph fills bits 15..6, so bits 5..0 are always clear.

#include <cstdint>

