// One scan line of glyph `code` (screen byte & 0x7F). bit 15 = leftmost dot; rows outside
// the cell read blank so callers need no bound beyond kRows.
inline uint16_t glyphRow(uint8_t code, int row) {
    if (row < 0 || row >= kRows) return 0;
    return charset()[code & 0x7F][row];
}

